INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m33667$nota-0221$m33667$, $m33668$VO2 Max Essentials_Final.pdf$m33668$, $m33669$46$m33669$, $m33670$Long slow distance running: continuous run at 70% of maximal heart rate for 45 minutes. Lactate threshold running: continuous run at lactate threshold (85% of maximal heart rate) for ~25 minutes. 15 on/15 off interval running: 45 repetitions of 15s work at 90%-95% max HR / 15s active rest at 70% max HR. 4 x 4-minute intervals: four 4-minute intervals at 90%-95% max HR, interspersed with 3 minutes of active rest at 70% max HR. Each protocol performed 3 days/week for 8 weeks... all protocols were matched for oxygen consumption.$m33670$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m33671$nota-0221$m33671$, $m33672$VO2 Max Essentials_Final.pdf$m33672$, $m33673$47$m33673$, $m33674$an increase of 6.4% was observed in the 15 on/15 off group and an increase of 8.8% was observed in the 4 x 4 interval group. Contrast this with the nonsignificant 1.8% increase after long slow distance training and a similarly nonsignificant increase of 2.0% in the lactate threshold training group... both of the high-intensity interval protocols also increased maximal stroke volume after training... 'high-aerobic intensity endurance interval training is significantly more effective than performing the same total work at either lactate threshold or at 70% heart rate max in improving VO2 max.' [Helgerud J, et al. Med Sci Sports Exerc. 2007;39(4):665-671.]$m33674$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m33675$nota-0221$m33675$, $m33676$nota-0042$m33676$, $m33677$complementa$m33677$, $m33678$fornece um protocolo específico e validado (4×4min) com evidência comparativa de eficácia, enriquecendo a janela de duração de estímulo de VO2máx já registrada na nota-0042$m33678$)
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m33679$nota-0221$m33679$, $m33680$nota-0199$m33680$, $m33681$complementa$m33681$, $m33682$corrobora e detalha, com dados comparativos de eficácia, o exemplo '6×4min' já citado no catálogo de sessões da nota-0199 (Fonte 2)$m33682$)
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m33683$nota-0221$m33683$, $m33684$nota-0157$m33684$, $m33685$complementa$m33685$, $m33686$débito cardíaco/volume sistólico (nota-0157), citado no corpo da nota como mecanismo central provável do ganho de VO2máx — link estrutural ausente até auditoria de 2026-08-02$m33686$)
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m33687$nota-0221$m33687$, $m33688$nota-0210$m33688$, $m33689$complementa$m33689$, $m33690$fatores centrais vs. periféricos (nota-0210), citada junto com nota-0157 no corpo da nota como o mecanismo central do maior ganho de VO2máx — link estrutural ausente até auditoria de 2026-08-02$m33690$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m33691$nota-0222$m33691$, $m33692$VO2 Max Essentials_Final.pdf$m33692$, $m33693$48$m33693$, $m33694$Work intervals were classified as long intervals (more than 2 minutes), moderate intervals (30s to 2min), short intervals (10-30s) and sprint intervals (less than 10s). The volume of HIIT (bout duration x repetitions) was classified as high volume (>15min total), moderate (5-10min), low (<5min)... A total of 1,514 participants... [Wen D, et al. J Sci Med Sport. 2019;22(8):941-947.]$m33694$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m33695$nota-0222$m33695$, $m33696$VO2 Max Essentials_Final.pdf$m33696$, $m33697$50$m33697$, $m33698$longer intervals (more than 2 minutes), higher volume training (more than 15 minutes total per session), and longer training periods (4 to 12 weeks) seem to be more effective... The primary driver of improvements in VO2 max with any of the training protocols seems to be session volume. In other words, you can perform very short sprint intervals of 30 seconds or less, but you need to do a lot of them... The time spent at a high percentage of heart rate/VO2 max is what's important, and many roads lead to Rome.$m33698$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m33699$nota-0222$m33699$, $m33700$VO2 Max Essentials_Final.pdf$m33700$, $m33701$50$m33701$, $m33702$if you wish to perform short or sprint-type intervals, these need to be at all 'all-out' intensity... If choosing to perform longer duration intervals, a submaximal (though still very hard) intensity is sufficient.$m33702$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m33703$nota-0222$m33703$, $m33704$nota-0221$m33704$, $m33705$complementa$m33705$, $m33706$generaliza, com meta-análise de 1.514 participantes, o achado específico de um protocolo (4x4min) da nota-0221 para uma regra mais ampla sobre volume total de HIIT$m33706$)
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m33707$nota-0222$m33707$, $m33708$nota-0042$m33708$, $m33709$complementa$m33709$, $m33710$reforça, com nova evidência, a janela de duração de estímulo de VO2máx já registrada na nota-0042 do Livro 1$m33710$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m33711$nota-0246$m33711$, $m33712$Exercise Physiology McArdle.pdf$m33712$, $m33713$488$m33713$, $m33714$The relief interval is either passive (rest–relief) or active (work–relief). A ratio of exercise duration to recovery duration usually formulates the duration of the relief interval. The ratio 1:3 generally applies to training the immediate energy system. For a sprinter who runs 10-s intervals, the relief interval equals about 30 s (3 × 10 s). For training the short-term glycolytic energy system, the relief interval averages twice the exercise interval, or a ratio of 1:2.$m33714$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m33715$nota-0246$m33715$, $m33716$Exercise Physiology McArdle.pdf$m33716$, $m33717$488$m33717$, $m33718$The optimal exercise-to relief interval ratio usually is 1:1 or 1:1.5 to train the long-term aerobic energy system. During a 60- to 90-s high-intensity exercise interval, oxygen consumption increases rapidly to a high level but remains inadequate to meet exercise energy requirements. The recommended relief interval causes the succeeding exercise interval to begin before complete recovery.$m33718$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m33719$nota-0246$m33719$, $m33720$nota-0221$m33720$, $m33721$complementa$m33721$, $m33722$nota-0221 (protocolo 4x4min norueguês) é um caso específico de treino de VO2máx; esta nota generaliza a lógica de razão trabalho:recuperação por sistema energético-alvo, incluindo sprint/potência anaeróbia não coberto por 0221$m33722$)
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m33723$nota-0246$m33723$, $m33724$nota-0186$m33724$, $m33725$complementa$m33725$, $m33726$aplica o princípio de especificidade (nota-0186) ao desenho de intervalos: a razão de recuperação deve ser escolhida conforme o sistema energético que se deseja sobrecarregar$m33726$)
